import heapq
from collections import defaultdict


def pass_route(
    n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]
) -> int:
    num_zones = len(prices)
    adj = defaultdict(list)
    for u, v, cost, zone in edges:
        adj[u].append((v, cost, zone))
        adj[v].append((u, cost, zone))

    station_passes = defaultdict(list)
    for stop, z in stations:
        station_passes[stop].append(z)

    # dist[node][mask]
    dist = {}
    pq = [(0, 0, 0)]  # (current_cost, u, mask)
    dist[(0, 0)] = 0

    while pq:
        d, u, mask = heapq.heappop(pq)

        if d > dist.get((u, mask), float("inf")):
            continue

        if u == n - 1:
            return d

        # Option 1: Buy passes available at this stop
        if u in station_passes:
            for z in station_passes[u]:
                if not (mask & (1 << z)):
                    new_mask = mask | (1 << z)
                    new_d = d + prices[z]
                    if new_d < dist.get((u, new_mask), float("inf")):
                        dist[(u, new_mask)] = new_d
                        heapq.heappush(pq, (new_d, u, new_mask))

        # Option 2: Take an edge
        for v, cost, zone in adj[u]:
            ride_cost = 0 if (zone != -1 and (mask & (1 << zone))) else cost
            new_d = d + ride_cost
            if new_d < dist.get((v, mask), float("inf")):
                dist[(v, mask)] = new_d
                heapq.heappush(pq, (new_d, v, mask))

    return -1
